(function () {
  "use strict";

  const form = document.getElementById("prefs-form");
  const status = document.getElementById("form-status");

  if (!form || !status) return;

  const labels = {
    email: "Email",
    sms: "SMS",
    push: "Push Notifications"
  };

  form.addEventListener("submit", function (event) {
    event.preventDefault();

    const selected = form.elements["notifications"].value;

    if (!selected) {
      status.textContent = "Please choose a notification method.";
      status.classList.remove("is-success");
      status.classList.add("is-error");
      const firstRadio = form.querySelector('input[name="notifications"]');
      if (firstRadio) firstRadio.focus();
      return;
    }

    status.textContent = "Preferences saved. We'll notify you via " + labels[selected] + ".";
    status.classList.remove("is-error");
    status.classList.add("is-success");
  });
})();

