(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();
  const file = "file://" + path.resolve(__dirname, "index.html");
  await page.goto(file, { waitUntil: "load" });
  await page.addScriptTag({ path: "/tmp/axe.min.js" });
  const results = await page.evaluate(async () => await window.axe.run());
  await browser.close();
  const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));
  const bp = results.violations.filter(v => v.tags.includes("best-practice"));
  const out = {
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, help: v.help, targets: v.nodes.map(n => n.target) }))
  };
  console.log(JSON.stringify(out, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();

